SELECT store_yearly.sr_store_sk, store_yearly.year, store_yearly.yearly_return_amt, store_yearly.prior_year_return_amt, CASE WHEN store_yearly.prior_year_return_amt = 0 THEN NULL ELSE (store_yearly.yearly_return_amt - store_yearly.prior_year_return_amt) * 100.0 / store_yearly.prior_year_return_amt END AS yoy_growth_percent, CASE WHEN (store_yearly.yearly_return_amt - store_yearly.prior_year_return_amt) * 100.0 / NULLIF(store_yearly.prior_year_return_amt, 0) > 20 THEN 'High Growth' ELSE 'Normal Growth' END AS growth_category, DENSE_RANK() OVER (ORDER BY CASE WHEN store_yearly.prior_year_return_amt = 0 THEN 0 ELSE (store_yearly.yearly_return_amt - store_yearly.prior_year_return_amt) * 100.0 / store_yearly.prior_year_return_amt END DESC) AS yoy_growth_rank FROM ( SELECT sr.sr_store_sk, d_ret.d_year AS year, SUM(sr.sr_return_amt) AS yearly_return_amt, LAG(SUM(sr.sr_return_amt)) OVER (PARTITION BY sr.sr_store_sk ORDER BY d_ret.d_year) AS prior_year_return_amt FROM store_returns sr JOIN date_dim d_ret ON sr.sr_returned_date_sk = d_ret.d_date_sk JOIN time_dim t ON sr.sr_return_time_sk = t.t_time_sk LEFT JOIN call_center cc ON cc.cc_closed_date_sk = d_ret.d_date_sk WHERE t.t_shift = 'Evening' GROUP BY sr.sr_store_sk, d_ret.d_year ) AS store_yearly
